package com.wayrapass.repository;
import com.wayrapass.model.Vehicle; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*;
public interface VehicleRepository extends JpaRepository<Vehicle,Long>{ boolean existsByPlateIgnoreCase(String plate); boolean existsByPlateIgnoreCaseAndIdNot(String plate,Long id); boolean existsByQrToken(String token); boolean existsByQrTokenAndIdNot(String token,Long id); Optional<Vehicle> findByQrToken(String token); List<Vehicle> findAllByOrderByIdAsc(); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select v from Vehicle v where v.id=:id") Optional<Vehicle> findByIdForUpdate(Long id); }
